step3_testbench.spice:
* Regulated Cascode Current Mirror Testbench
.lib ${SKY130_PDK} tt

* Define parameters used in netlist
.param W_xm2=5u L_xm2=1u
.param W_xm3=5u L_xm3=1u
.param W_xm1=5u L_xm1=1u
.param W_xm4=5u L_xm4=1u
.param W_xm5=10u L_xm5=1u
.param W_xma3=10u L_xma3=1u
.param W_xma1=5u L_xma1=1u
.param W_xma4=10u L_xma4=1u
.param W_xma2=5u L_xma2=1u
.param W_xmsu2=10u L_xmsu2=1u
.param W_xmsu1=5u L_xmsu1=1u
.param W_xmsu3=5u L_xmsu3=1u
.param W_xm6=5u L_xm6=1u
.param W_xm7=10u L_xm7=1u
.param W_xm8=5u L_xm8=1u

* --- DUT ---
VDD VDD 0 1.8
xm2 N005 N002 0 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
Vo N001 0 0
X_U1 Vbiasn Vbiasp VDD 0 SUB_1
xm3 N002 N003 N006 0 sky130_fd_pr__nfet_01v8 w={W_xm3} l={L_xm3}
xm1 N006 N002 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
xm4 N001 N004 N005 0 sky130_fd_pr__nfet_01v8 w={W_xm4} l={L_xm4}
xm5 N002 Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm5} l={L_xm5}
xma3 N003 Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma3} l={L_xma3}
xma1 N003 N006 0 0 sky130_fd_pr__nfet_01v8 w={W_xma1} l={L_xma1}
xma4 N004 Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma4} l={L_xma4}
xma2 N004 N005 0 0 sky130_fd_pr__nfet_01v8 w={W_xma2} l={L_xma2}

.subckt SUB_1 Vbiasn Vbiasp VDD GND
  xmsu2 N002 N002 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xmsu2} l={L_xmsu2}
  xmsu1 N002 Vbiasn GND 0 sky130_fd_pr__nfet_01v8 w={W_xmsu1} l={L_xmsu1}
  xmsu3 Vbiasp N002 Vbiasn 0 sky130_fd_pr__nfet_01v8 w={W_xmsu3} l={L_xmsu3}
  xm3 Vbiasn Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm3} l={L_xm3}
  xm4 N003 Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm4} l={L_xm4}
  xm1 Vbiasn Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
  R1 N004 0 5.5k
  xma4 Vbiasp N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma4} l={L_xma4}
  xma3 N001 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma3} l={L_xma3}
  xm5 N001 N003 0 0 sky130_fd_pr__nfet_01v8 w={W_xm5} l={L_xm5}
  xm7 VDD Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm7} l={L_xm7}
  xm8 0 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm8} l={L_xm8}
  xm2 Vbiasp Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
  xm6 N003 N003 N004 0 sky130_fd_pr__nfet_01v8 w={W_xm6} l={L_xm6}
.ends SUB_1

.control
  * 1. DC Sweep for Output Resistance and Minimum Output Voltage
  dc Vo 0 1.8 0.01
  let i_out = -i(Vo)

  * Measure nominal current at Vo = 1.0V
  meas dc i_nom find i_out at=1.0

  * Measure output resistance around 1.0V
  meas dc i_high find i_out at=1.1
  meas dc i_low find i_out at=0.9
  let ro_meas = 0.2 / (i_high - i_low)
  print ro_meas

  * Measure minimum output voltage (where current drops to 95% of nominal)
  let i_target = 0.95 * i_nom
  meas dc v_omin when i_out=i_target
  print v_omin

  * 2. Temperature Sweep for TCI_REF
  alter Vo 1.0
  dc temp 0 100 10
  let i_ref_temp = -i(Vo)
  meas dc i_ref_27 find i_ref_temp at=27
  meas dc i_ref_100 find i_ref_temp at=100
  let tc_iref = ((i_ref_100 - i_ref_27) / i_ref_27) / (100 - 27) * 1e6
  print tc_iref

  quit
.endc
.end

